CREATE TABLE IF NOT EXISTS TB_EEP_CARD_M ( CARD_SQ int NOT NULL AUTO_INCREMENT , CARD_NM varchar(50) NOT NULL , CARD_CO varchar(30) NULL COMMENT '카드사' , LAST4 char(4) NOT NULL COMMENT '카드번호 끝 4자리만 둔다' , HOLDER_NM varchar(30) NULL COMMENT '사용자' , USE_YN char(1) NOT NULL DEFAULT 'Y' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (CARD_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='법인카드';
CREATE TABLE IF NOT EXISTS TB_EEP_CARD_USE_D ( USE_SQ int NOT NULL AUTO_INCREMENT , CARD_SQ int NOT NULL , USE_DT date NOT NULL , AMT bigint NOT NULL COMMENT '원. 취소는 음수' , USE_CD varchar(20) NOT NULL COMMENT '공통코드 CARD_USE' , DETAIL varchar(500) NULL COMMENT '사용 상세 내용' , MERCHANT varchar(200) NULL COMMENT '정산 때 엑셀에서 붙인 가맹점' , REG_EMPLY_ID varchar(50) NULL , REG_DT datetime NULL , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (USE_SQ) , KEY IX_CARD_USE_MONTH (CARD_SQ, USE_DT) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='법인카드 사용 내역';
CREATE TABLE IF NOT EXISTS TB_EEP_CARD_SETTLE_M ( CARD_SQ int NOT NULL , YM char(7) NOT NULL , FILE_NM varchar(200) NULL , EXCEL_CNT int NOT NULL DEFAULT 0 , MATCH_CNT int NOT NULL DEFAULT 0 , DONE_EMPLY_ID varchar(50) NULL , DONE_DT datetime NULL , PRIMARY KEY (CARD_SQ, YM) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='법인카드 월 정산 확정';
INSERT INTO TB_EEP_COMN_CD_M (COMN_CD, COMN_CD_NM, USE_YN, DEL_YN, REG_DT) SELECT 'CARD_USE', '법인카드 사용처', 'Y', 'N', DATE_FORMAT(NOW(), '%Y-%m-%d') FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TB_EEP_COMN_CD_M C WHERE C.COMN_CD = 'CARD_USE' AND C.DEL_YN = 'N');
INSERT INTO TB_EEP_COMN_DTL_CD_S (COMN_CD_SQ, COMN_DTL_CD, COMN_DTL_CD_NM, COMN_DTL_CD_ORD, USE_YN, DEL_YN, REG_DT) SELECT C.COMN_CD_SQ, V.CD, V.NM, V.ORD, 'Y', 'N', DATE_FORMAT(NOW(), '%Y-%m-%d') FROM ( SELECT 'MEAL' CD, '식대' NM, 1 ORD UNION ALL SELECT 'DINNER', '회식', 2 UNION ALL SELECT 'SUPPLY', '비품·소모품', 3 UNION ALL SELECT 'TRANS', '교통·주유', 4 UNION ALL SELECT 'PARK', '주차·통행료', 5 UNION ALL SELECT 'TRIP', '출장·숙박', 6 UNION ALL SELECT 'ENT', '접대', 7 UNION ALL SELECT 'EDU', '도서·교육', 8 UNION ALL SELECT 'SW', '소프트웨어·구독', 9 UNION ALL SELECT 'COMM', '통신', 10 UNION ALL SELECT 'POST', '택배·우편', 11 UNION ALL SELECT 'EVENT', '경조사', 12 UNION ALL SELECT 'ETC', '기타', 13 ) V JOIN TB_EEP_COMN_CD_M C ON C.COMN_CD = 'CARD_USE' AND C.DEL_YN = 'N' WHERE NOT EXISTS (SELECT 1 FROM TB_EEP_COMN_DTL_CD_S D WHERE D.COMN_CD_SQ = C.COMN_CD_SQ);
INSERT INTO TB_EEP_MENU (MENU_CODE, MENU_NM, REL_CODE, MENU_DEPTH, MENU_URL, ICON_NM, FRST_REG_DT, LAST_UPDT_DT, FRST_REGISTER, SORT_NO, USE_YN, AUTH_PATTERN, NEW_WIN_YN) SELECT 'K00001', '법인카드', REL_CODE, MENU_DEPTH, '/admin/card/openCardList.do', 'fa-credit-card', NOW(), NOW(), 'system', SORT_NO + 1, 'Y', '/admin/card/**', 'N' FROM TB_EEP_MENU WHERE MENU_CODE = 'E001' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_MENU) M WHERE M.MENU_CODE = 'K00001'); INSERT IGNORE INTO TB_EEP_ROLE_MENU_R (ROLE_SQ, MENU_CODE) SELECT ROLE_SQ, 'K00001' FROM TB_EEP_ROLE_MENU_R WHERE MENU_CODE = 'E00001' AND NOT EXISTS (SELECT 1 FROM (SELECT MENU_CODE FROM TB_EEP_ROLE_MENU_R) R WHERE R.MENU_CODE = 'K00001');
ALTER TABLE TB_EEP_CARD_M ADD COLUMN IF NOT EXISTS STAFF_SQ int NULL COMMENT '사용자(TB_EEP_HR_STAFF_M)' AFTER HOLDER_NM; UPDATE TB_EEP_CARD_M C JOIN (SELECT STAFF_NM, MIN(STAFF_SQ) AS SQ FROM TB_EEP_HR_STAFF_M WHERE STATUS_CD <> 'LEFT' GROUP BY STAFF_NM HAVING COUNT(*) = 1) S ON S.STAFF_NM = C.HOLDER_NM SET C.STAFF_SQ = S.SQ WHERE C.STAFF_SQ IS NULL; INSERT INTO TB_EEP_ROLE_M (ROLE_CD, ROLE_NM, ROLE_DESC, SYSTEM_YN, SORT_NO) SELECT 'CARD', '법인카드 사용자', '본인 카드만 보기 (카드 사용자로 지정하면 자동으로 들어감)', 'Y', 90 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT ROLE_CD FROM TB_EEP_ROLE_M) R WHERE R.ROLE_CD = 'CARD'); INSERT IGNORE INTO TB_EEP_ROLE_MENU_R (ROLE_SQ, MENU_CODE) SELECT ROLE_SQ, 'K00001' FROM TB_EEP_ROLE_M WHERE ROLE_CD = 'CARD'; INSERT IGNORE INTO TB_EEP_USER_ROLE_R (EMPLY_ID, ROLE_SQ, REG_EMPLY_ID) SELECT S.EMPLY_ID, R.ROLE_SQ, 'system' FROM TB_EEP_CARD_M C JOIN TB_EEP_HR_STAFF_M S ON S.STAFF_SQ = C.STAFF_SQ JOIN TB_EEP_ROLE_M R ON R.ROLE_CD = 'CARD' WHERE C.USE_YN = 'Y' AND S.EMPLY_ID IS NOT NULL AND S.EMPLY_ID <> '';
ALTER TABLE TB_EEP_CARD_USE_D ADD COLUMN IF NOT EXISTS TARGET_NM varchar(100) NULL COMMENT '대상' AFTER MERCHANT , ADD COLUMN IF NOT EXISTS CLOSE_EMPLY_ID varchar(50) NULL AFTER TARGET_NM , ADD COLUMN IF NOT EXISTS CLOSE_DT datetime NULL COMMENT '마감 시각(KST). 있으면 수정 불가' AFTER CLOSE_EMPLY_ID;

