SELECT C.CARD_SQ, C.CARD_NM, C.CARD_CO, C.LAST4, C.STAFF_SQ, IFNULL(H.STAFF_NM, C.HOLDER_NM) AS HOLDER_NM, H.EMPLY_ID AS HOLDER_ID, C.USE_YN , (SELECT COUNT(*) FROM TB_EEP_CARD_USE_D U WHERE U.CARD_SQ = C.CARD_SQ AND DATE_FORMAT(U.USE_DT, '%Y-%m') = #{YM}) AS MONTH_CNT , (SELECT IFNULL(SUM(U.AMT), 0) FROM TB_EEP_CARD_USE_D U WHERE U.CARD_SQ = C.CARD_SQ AND DATE_FORMAT(U.USE_DT, '%Y-%m') = #{YM}) AS MONTH_AMT , (SELECT DATE_FORMAT(MAX(U.USE_DT), '%Y-%m') FROM TB_EEP_CARD_USE_D U WHERE U.CARD_SQ = C.CARD_SQ AND U.CLOSE_DT IS NOT NULL) AS LAST_CLOSE_YM FROM TB_EEP_CARD_M C LEFT JOIN TB_EEP_HR_STAFF_M H ON H.STAFF_SQ = C.STAFF_SQ
C.CARD_SQ = #{CARD_SQ} AND H.EMPLY_ID = #{ME}
ORDER BY C.USE_YN DESC, C.CARD_NM

