UPDATE TB_EEP_CARD_M
SET CARD_NM = #{CARD_NM}, CARD_CO = NULLIF(#{CARD_CO}, ''), LAST4 = #{LAST4}, HOLDER_NM = #{HOLDER_NM}, STAFF_SQ = #{STAFF_SQ}, USE_YN = #{USE_YN}, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE CARD_SQ = #{CARD_SQ}
